// Inlined so Cloudflare never fetches them. Polish rewrites
// PNG/JPEG to WebP while leaving the original Content-Type;
// Safari with nosniff then refuses to paint the file, and our
// onError handlers hide the mark. A data URI is not a request,
// so Polish cannot touch it. no-transform does not stop Polish
// on this zone (verified 2026-09, cache-MISS of grace-logo.png).
export const graceLogo = 'data:image/png;base64,';
export const griffinLogo = 'data:image/webp;base64,';
